// Classify Error: extracts error metadata, classifies severity, and formats alerts
const errData = $input.first().json || {};
const execution = errData.execution || {};
const workflow = errData.workflow || {};
const errObj = execution.error || errData.error || {};

const workflowName = workflow.name || 'Unknown Workflow';
const workflowId = workflow.id || '';
const executionId = execution.id || 'N/A';
const executionUrl = execution.url || '';
const nodeName = execution.lastNodeExecuted || errObj.node?.name || 'Unknown Node';
const rawMessage = String(errObj.message || errObj.description || 'Unknown workflow error').trim();
const httpCode = String(errObj.httpCode || errObj.statusCode || errObj.cause?.status || '');
const timestamp = new Date().toISOString();

const msgLower = rawMessage.toLowerCase();

// Classify error category & severity
let category = 'runtime';
let severity = 'warning';

if (
  msgLower.includes('invalid_grant') ||
  msgLower.includes('unauthorized') ||
  msgLower.includes('forbidden') ||
  msgLower.includes('token') ||
  httpCode === '401' ||
  httpCode === '403'
) {
  category = 'auth';
  severity = 'critical';
} else if (
  msgLower.includes('quota') ||
  msgLower.includes('rate limit') ||
  msgLower.includes('429') ||
  msgLower.includes('service unavailable') ||
  msgLower.includes('high demand') ||
  httpCode === '429' ||
  httpCode === '503'
) {
  category = 'api_transient';
  severity = 'warning';
} else if (
  msgLower.includes('timeout') ||
  msgLower.includes('econnrefused') ||
  msgLower.includes('enotfound') ||
  msgLower.includes('network')
) {
  category = 'network';
  severity = 'critical';
} else if (
  msgLower.includes('sheet') ||
  msgLower.includes('not found') ||
  msgLower.includes('whatsapp') ||
  msgLower.includes('telegram') ||
  httpCode.startsWith('5')
) {
  category = 'integration';
  severity = 'critical';
}

const isCritical = severity === 'critical';
const badge = isCritical ? '🚨 CRITICAL' : '⚠️ WARNING';

const telegramText = [
  `${badge} — Dawaa Pharmacy Error`,
  `Workflow: ${workflowName}`,
  `Node: ${nodeName}`,
  `Category: ${category}${httpCode ? ` (HTTP ${httpCode})` : ''}`,
  `Execution ID: ${executionId}`,
  `Error: ${rawMessage}`,
  executionUrl ? `Link: ${executionUrl}` : ''
].filter(Boolean).join('\n');

const emailSubject = `[${severity.toUpperCase()}] Dawaa n8n Error in ${workflowName} (${nodeName})`;
const emailBody = [
  `A ${severity.toUpperCase()} error occurred in your Dawaa Pharmacy automation.`,
  '',
  `Timestamp: ${timestamp}`,
  `Workflow: ${workflowName} (${workflowId})`,
  `Failed Node: ${nodeName}`,
  `Category: ${category}`,
  `HTTP Code: ${httpCode || 'N/A'}`,
  `Execution ID: ${executionId}`,
  executionUrl ? `Execution URL: ${executionUrl}` : '',
  '',
  'Error Details:',
  rawMessage
].filter(line => line !== null).join('\n');

return [{
  json: {
    timestamp,
    severity,
    is_critical: isCritical,
    category,
    http_code: httpCode,
    workflow_name: workflowName,
    workflow_id: workflowId,
    node_name: nodeName,
    execution_id: executionId,
    execution_url: executionUrl,
    error_message: rawMessage,
    telegram_text: telegramText,
    email_subject: emailSubject,
    email_body: emailBody
  }
}];

// Expired Lines: finds active/pending reservations whose expires_at timestamp has passed
const reservations = $('Read Reservations').all().map(i => i.json);
const nowMs = Date.now();
const expirableStatuses = new Set(['reserved', 'approved', 'pending_pharmacist']);

const expired = [];

for (const row of reservations) {
  const status = String(row.status || '').trim().toLowerCase();
  if (!expirableStatuses.has(status)) continue;

  const expiresRaw = String(row.expires_at || '').trim();
  if (!expiresRaw) continue;

  const expiresMs = Date.parse(expiresRaw);
  if (Number.isNaN(expiresMs) || expiresMs > nowMs) continue;

  const prevNote = String(row.note || '').trim();
  const expiredNote = prevNote
    ? `${prevNote} | Expired at ${new Date(nowMs).toISOString()}`
    : `Expired at ${new Date(nowMs).toISOString()}`;

  expired.push({
    json: {
      row_number: row.row_number,
      res_id: String(row.res_id || ''),
      customer_id: String(row.customer_id || row.wa_phone_id || ''),
      wa_phone_id: String(row.wa_phone_id || ''),
      customer_name: String(row.customer_name || 'Customer'),
      sku: String(row.sku || ''),
      name: String(row.name || row.sku || 'medicine'),
      qty: Number(row.qty || 1),
      previous_status: status,
      status: 'expired',
      note: expiredNote
    }
  });
}

return expired;

// Restock Totals: calculates Catalog stock to return for expired stock-deducted reservations
const reservations = $('Read Reservations').all().map(i => i.json);
const catalog = $input.all().map(i => i.json);
const nowMs = Date.now();

// Only 'reserved' and 'approved' lines deducted stock from Catalog
const stockDeductedStatuses = new Set(['reserved', 'approved']);
const returnBySku = new Map();

for (const row of reservations) {
  const status = String(row.status || '').trim().toLowerCase();
  if (!stockDeductedStatuses.has(status)) continue;

  const expiresRaw = String(row.expires_at || '').trim();
  if (!expiresRaw) continue;

  const expiresMs = Date.parse(expiresRaw);
  if (Number.isNaN(expiresMs) || expiresMs > nowMs) continue;

  const sku = String(row.sku || '').trim();
  if (!sku || sku === 'UNMATCHED' || sku === 'MANUAL_REVIEW') continue;

  const qty = Math.max(0, Number(row.qty || 0));
  if (qty <= 0) continue;

  returnBySku.set(sku, (returnBySku.get(sku) || 0) + qty);
}

if (returnBySku.size === 0) return [];

const catalogMap = new Map(catalog.map(c => [String(c.sku || '').trim(), c]));
const updates = [];

for (const [sku, addQty] of returnBySku.entries()) {
  const item = catalogMap.get(sku);
  if (!item) continue;
  const currentStock = Number(item.stock || 0);
  updates.push({
    json: {
      sku,
      name: item.name || sku,
      previous_stock: currentStock,
      returned_qty: addQty,
      stock: currentStock + addQty
    }
  });
}

return updates;

// Find Low Stock: identifies Catalog SKUs at or below reorder_level and builds the daily reorder report
const catalog = $input.all().map(i => i.json);

const lowItems = catalog
  .filter(row => {
    const sku = String(row.sku || '').trim();
    if (!sku) return false;
    const stock = Number(row.stock);
    const reorder = Number(row.reorder_level);
    return !Number.isNaN(stock) && !Number.isNaN(reorder) && stock <= reorder;
  })
  .sort((a, b) => Number(a.stock) - Number(b.stock));

// Stop here if every SKU is above its reorder level
if (lowItems.length === 0) return [];

const dateStr = new Date().toLocaleDateString('en-GB', { timeZone: 'Africa/Cairo' });

const lines = lowItems.map((item, idx) => {
  const stock = Number(item.stock || 0);
  const reorder = Number(item.reorder_level || 0);
  const suggestedOrder = Math.max(reorder * 2 - stock, reorder);
  const tag = stock === 0 ? '🔴 OUT OF STOCK' : '🟠 LOW';
  return `${idx + 1}. ${tag} ${item.name} (${item.strength || '-'}) [${item.sku}] — Stock: ${stock} / Reorder: ${reorder} → Order ~${suggestedOrder}`;
});

const telegramText = [
  `📦 Dawaa Pharmacy — Daily Reorder List (${dateStr})`,
  `${lowItems.length} item(s) at or below reorder level:`,
  '',
  ...lines
].join('\n');

const emailSubject = `Dawaa Pharmacy Reorder List (${dateStr}) — ${lowItems.length} Low-Stock Item(s)`;
const emailBody = [
  `Daily Low-Stock Reorder Report — ${dateStr}`,
  `Items at or below reorder level: ${lowItems.length}`,
  '',
  ...lines,
  '',
  'Generated automatically by Dawaa n8n Maintenance Workflow.'
].join('\n');

return [{
  json: {
    report_date: dateStr,
    low_stock_count: lowItems.length,
    items: lowItems,
    telegram_text: telegramText,
    email_subject: emailSubject,
    email_body: emailBody
  }
}];
